function formatValue(v, isMoney, isPercent, short, forReport) {
  if (isMoney && forReport) return v.toFixed(2) + ' ₽'
  if (isMoney && short) return Math.round(v / 1000) + ' тыс.'
  if (isPercent) return Math.round(v * 100) + '%'
  return String(v)
}
